-- noinspection SqlDialectInspection
-- Development/test-only inventory fixture. Never run automatically at backend startup.
-- The current schema is migrated first; this script is guarded against non-dev/test databases.
-- Seed identities are the former user-visible inventory numbers; no independent external_id is evidenced.

BEGIN;

DO $$ BEGIN
  IF right(current_database(), 4) <> '_dev' AND right(current_database(), 5) <> '_test' THEN
    RAISE EXCEPTION 'Refusing destructive seed outside an explicitly named _dev or _test database';
  END IF;
END $$;

TRUNCATE TABLE light_points RESTART IDENTITY CASCADE;

